<section class="section blog-collection">
 <p class="eyebrow">WEDDING JOURNAL</p><h1><?=e(t('blog.title'))?></h1><p class="blog-description"><?=e(t('blog.description'))?></p>
 <nav class="blog-categories" aria-label="<?=e(t('blog.categories'))?>"><a class="<?=$category===''?'active':''?>" href="<?=e(\App\Services\Seo::localizedUrl('/blog',$lang))?>"><?=e(t('all'))?></a><?php foreach($categories as $cat):?><a class="<?=$category===$cat?'active':''?>" href="<?=e(\App\Services\Seo::localizedUrl('/blog',$lang,['category'=>$cat]))?>"><?=e(t($cat))?></a><?php endforeach;?></nav>
 <div class="blog-grid"><?php foreach($posts as $r):?><article class="blog-card"><a class="blog-image" href="<?=e(site_url(['post'=>$r['slug']]))?>"><img loading="lazy" decoding="async" src="<?=e($r['cover'])?>" alt="<?=e(field($r,'cover_alt')?:field($r,'title'))?>"></a><div class="card-meta"><span><?=e(field($r,'category'))?></span><time datetime="<?=e(($r['publish_at']??'')?:$r['_created_at'])?>"><?=e(date('d.m.Y',strtotime(($r['publish_at']??'')?:$r['_created_at'])))?></time></div><h2><a href="<?=e(site_url(['post'=>$r['slug']]))?>"><?=e(field($r,'title'))?></a></h2><p><?=e(field($r,'excerpt'))?></p><a class="text-link" href="<?=e(site_url(['post'=>$r['slug']]))?>"><?=e(t('blog.read'))?> ↗</a></article><?php endforeach;?></div>
 <?php if(!$posts):?><div class="blog-empty"><span>✳</span><h2><?=e(t('blog.empty'))?></h2><p><?=e(t('blog.empty_description'))?></p></div><?php endif;?>
 <?php if($totalPages>1):?><nav class="pagination" aria-label="Pagination"><?php for($i=1;$i<=$totalPages;$i++):?><a <?=$currentPage===$i?'aria-current="page"':''?> href="<?=e(\App\Services\Seo::localizedUrl('/blog',$lang,array_filter(['p'=>$i>1?$i:null,'category'=>$category?:null])))?>"><?=$i?></a><?php endfor;?></nav><?php endif;?>
</section>
